// NewClient constructs a Redis client from the supplied cache configuration.
//
// When TLS is required the client is configured to use TLS 1.2 at minimum.
// A custom CA bundle can be provided either inline (ca_cert_bytes) or via a
// file path (ca_cert_path). When neither is supplied the system certificate
// authorities are used. Setting insecure_skip_tls disables certificate
// verification entirely.
func NewClient(cfg config.RedisCacheConfig) (*goredis.Client, error) {
	tlsConfig, err := tlsConfig(cfg)
	if err != nil {
		return nil, err
	}

	return goredis.NewClient(&goredis.Options{
		Addr:            fmt.Sprintf("%s:%d", cfg.Host, cfg.Port),
		TLSConfig:       tlsConfig,
		Username:        cfg.Username,
		Password:        cfg.Password,
		DB:              cfg.DB,
		PoolSize:        cfg.PoolSize,
		MinIdleConns:    cfg.MinIdleConn,
		ConnMaxIdleTime: cfg.ConnMaxIdleTime,
		DialTimeout:     cfg.NetTimeout,
		ReadTimeout:     cfg.NetTimeout * 2,
		WriteTimeout:    cfg.NetTimeout * 2,
		PoolTimeout:     cfg.NetTimeout * 2,
	}), nil
}

func tlsConfig(cfg config.RedisCacheConfig) (*tls.Config, error) {
	if !cfg.RequireTLS {
		return nil, nil
	}

	config := &tls.Config{
		MinVersion: tls.VersionTLS12,
	}

	caCert, err := caBundle(cfg)
	if err != nil {
		return nil, err
	}

	if len(caCert) > 0 {
		certPool := x509.NewCertPool()
		certPool.AppendCertsFromPEM(caCert)
		config.RootCAs = certPool
	}

	if cfg.InsecureSkipTLS {
		config.InsecureSkipVerify = true
	}

	return config, nil
}

// caBundle returns the certificate data to trust. Inline bytes take precedence
// over a file path. When neither is configured an empty bundle is returned,
// which causes the client to fall back to the system certificate authorities.
func caBundle(cfg config.RedisCacheConfig) ([]byte, error) {
	if cfg.CaCertBytes != "" {
		return []byte(cfg.CaCertBytes), nil
	}

	if cfg.CaCertPath != "" {
		bytes, err := os.ReadFile(cfg.CaCertPath)
		if err != nil {
			return nil, err
		}

		return bytes, nil
	}

	return []byte{}, nil
}
